import tailwindcss from "@tailwindcss/vite";
import { tanstackRouter } from "@tanstack/router-plugin/vite";
import react from "@vitejs/plugin-react";
import { defineConfig } from "vite";

// File-based routing: generates src/routeTree.gen.ts from src/routes/. The header
// replaces TanStack's default one, whose `// @ts-nocheck` would exempt the tree
// from tsc; this tree is type-checked like any other source file.
const routerOptions = {
  target: "react",
  autoCodeSplitting: true,
  routeTreeFileHeader: [
    "/* Generated by TanStack Router from src/routes/; never edit by hand. */",
  ],
} as const;

// Plugins live here only; vitest.config.ts merges this file into its own.
// The router plugin runs before react(), as TanStack Router requires.
export default defineConfig({
  plugins: [tanstackRouter(routerOptions), react(), tailwindcss()],
});
